1|// Which drawing skin to use for the "Picture this" loading slot.
2|// A skin seam (data-skin on <html>, ?skin= param) lives on another
3|// branch; until it lands this reads the same sources directly and
4|// falls back to engraving. SSR-safe: no document means engraving.
5|"use client";
6|
7|import { useEffect, useState } from "react";
8|
9|export type PictureSkin = "engraving" | "watercolor" | "ink";
10|
11|const SKINS: readonly string[] = ["engraving", "watercolor", "ink"];
12|
13|function fromValue(value: string | null | undefined): PictureSkin {
14|  return value && (SKINS as readonly string[]).includes(value) ? (value as PictureSkin) : "engraving";
15|}
16|
17|export function pictureSkin(): PictureSkin {
18|  if (typeof document === "undefined") return "engraving";
19|  const attr = document.documentElement?.dataset?.skin;
20|  if (attr) return fromValue(attr);
21|  try {
22|    const param = new URLSearchParams(window.location.search).get("skin");
23|    return fromValue(param);
24|  } catch {
25|    return "engraving";
26|  }
27|}
28|
29|// First paint is always engraving so SSR HTML matches; the real skin
30|// applies in an effect once mounted.
31|export function usePictureSkin(): PictureSkin {
32|  const [skin, setSkin] = useState<PictureSkin>("engraving");
33|  useEffect(() => {
34|    setSkin(pictureSkin());
35|  }, []);
36|  return skin;
37|}

