94|export function usePictureLoaded(url: string) {
95|  // True once the ready image has actually loaded. Resets per url; a
96|  // cached image reports complete on mount, otherwise onLoad fires.
97|  const [loaded, setLoaded] = useState(false);
98|  useEffect(() => {
99|    setLoaded(false);
100|  }, [url]);
101|  const imgRef = useCallback((el: HTMLImageElement | null) => {
102|    if (el && el.complete && el.naturalWidth > 0) setLoaded(true);
103|  }, []);
104|  const markLoaded = useCallback(() => setLoaded(true), []);
105|  return { loaded, imgRef, markLoaded };
