108|export function PictureDraw({ skin, frozen }: { skin: PictureSkin; frozen?: boolean }) {
109|  const reducedMotion = useReducedMotion();
110|  // Frozen (or reduced motion) renders the static still: no timers, no
111|  // rAF, so the drawing stops the instant the card turns ready.
112|  const stillMode = frozen || reducedMotion;
113|  const uid = useId().replace(/[^a-zA-Z0-9]/g, "");
114|  const grainId = `pdg${uid}`;
115|  const softId = `pds${uid}`;
116|  const toolRef = useRef<SVGGElement | null>(null);
117|  const pathRefs = useRef<(SVGPathElement | null)[]>([]);
118|  // Passes accumulate: outline first, then shading depth on top. When
119|  // the base passes run out, further light layers keep appending, so
120|  // the tool keeps working but nothing already drawn is ever wiped.
121|  const [strokes, setStrokes] = useState<FlatStroke[]>(() =>
122|    [0, 1, 2, 3].flatMap((l) => strokesForSkin(skin, l)),
123|  );
124|  const nextLayer = useRef(4);
125|  useEffect(() => {
126|    nextLayer.current = 4;
127|    setStrokes([0, 1, 2, 3].flatMap((l) => strokesForSkin(skin, l)));
128|  }, [skin]);
129|  const strokesRef = useRef(strokes);
130|  strokesRef.current = strokes;
131|  const stillAll = useMemo(() => stillStrokes(skin), [skin]);
132|  const still = stillMode ? stillAll : null;
133|  const flat = still ?? strokes;
134|
135|  useEffect(() => {
136|    if (stillMode) return;
137|    const paths = pathRefs.current;
138|    const tool = toolRef.current;
139|    let dead = false;
140|    let frame = 0;
141|    const pos = { x: 340, y: 304 };
142|    const place = (x: number, y: number) => {
143|      pos.x = x;
144|      pos.y = y;
145|      tool?.setAttribute("transform", `translate(${x.toFixed(1)} ${y.toFixed(1)})`);
146|    };
147|    place(pos.x, pos.y);
148|
149|    const pointAt = (p: SVGPathElement, f: number): { x: number; y: number } | null => {
150|      try {
151|        if (typeof p.getPointAtLength !== "function" || typeof p.getTotalLength !== "function") return null;
152|        const pt = p.getPointAtLength(p.getTotalLength() * f);
153|        return { x: pt.x, y: pt.y };
154|      } catch {
155|        return null;
156|      }
157|    };
158|
159|    // Draw every stroke once, in order, and keep it: outline first,
160|    // then shading layers on top. Past the base passes, further light
161|    // layers append so the tool keeps working without ever wiping.
162|    let i = 0;
163|    const stepStroke = () => {
164|      if (dead) return;
165|      if (i >= strokesRef.current.length) {
166|        const layer = strokesForSkin(skin, nextLayer.current);
167|        nextLayer.current += 1;
168|        setStrokes((prev) => [...prev, ...layer]);
169|        let waits = 0;
170|        const poll = () => {
171|          if (dead) return;
172|          if ((pathRefs.current.length > i && pathRefs.current[i]) || waits++ > 120) stepStroke();
173|          else frame = requestAnimationFrame(poll);
174|        };
175|        frame = requestAnimationFrame(poll);
176|        return;
177|      }
178|      const el = paths[i];
179|      const spec = strokesRef.current[i];
180|      i += 1;
181|    if (!el || !spec) {
182|      stepStroke();
183|      return;
184|    }
185|    const dur = Math.min(1400, Math.max(150, spec.d.length * 3));
186|    const start = pointAt(el, 0);
187|    const t0 = performance.now();
188|    const TRAVEL = 100;
189|    const tick = (now: number) => {
190|      if (dead) return;
191|      if (now - t0 < TRAVEL) {
192|        if (start) {
193|          const k = (now - t0) / TRAVEL;
194|          place(pos.x + (start.x - pos.x) * k, pos.y + (start.y - pos.y) * k);
195|        }
196|        frame = requestAnimationFrame(tick);
197|        return;
198|      }
199|      const k = Math.min(1, (now - t0 - TRAVEL) / dur);
200|      if (spec.fill) {
201|        el.setAttribute("opacity", String(spec.opacity * k));
202|        if (k < 1) place(pos.x + Math.sin(k * 9) * 3, pos.y + Math.cos(k * 7) * 2);
203|      } else {
204|        el.setAttribute("opacity", String(spec.opacity));
205|        el.style.strokeDashoffset = String(1 - k);
206|        const pt = pointAt(el, k);
207|        if (pt) place(pt.x, pt.y);
208|      }
209|      if (k < 1) frame = requestAnimationFrame(tick);
210|      else stepStroke();
211|    };
212|    frame = requestAnimationFrame(tick);
213|  };
214|  stepStroke();
215|  return () => {
216|    dead = true;
217|    cancelAnimationFrame(frame);
218|  };
219|}, [stillMode, skin]);
220|
221|  return (
222|    <>
223|      <svg
224|        className="picdraw-art"
225|        viewBox="0 0 300 380"
226|        preserveAspectRatio="xMidYMid slice"
227|        role="img"
228|        aria-label="Illustration being drawn"
229|      >
230|        <defs>
231|          <filter id={grainId} x="0" y="0" width="1" height="1">
232|            <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" seed="3" />
233|            <feColorMatrix values="0 0 0 0 .32 0 0 0 0 .25 0 0 0 0 .14 0 0 0 .10 0" />
234|          </filter>
235|          <filter id={softId} x="-50%" y="-50%" width="200%" height="200%">
236|            <feGaussianBlur stdDeviation="1.2" />
237|          </filter>
238|        </defs>
239|        <Paper skin={skin} grainId={grainId} />
240|        <g>
241|          {flat.map((s, i) => (
242|            <path
243|              key={i}
244|              ref={still ? undefined : (el) => {
245|                pathRefs.current[i] = el;
246|              }}
247|              d={s.d}
248|              fill={s.fill ?? "none"}
249|              stroke={s.stroke}
250|              strokeWidth={s.width || undefined}
251|              opacity={still ? s.opacity : 0}
252|              pathLength={s.fill ? undefined : 1}
253|              style={s.fill || still ? undefined : { strokeDasharray: "1", strokeDashoffset: "1" }}
254|              filter={s.blurred ? `url(#${softId})` : undefined}
255|              strokeLinecap="round"
256|              strokeLinejoin="round"
257|            />
258|          ))}
259|        </g>
260|        <g ref={toolRef} className="picdraw-tool" transform="translate(254 340)">
261|          <Tool skin={skin} />
262|        </g>
263|      </svg>
264|      <div className="picdraw-status">
265|        <span className="picdraw-t">{DRAW_STATUS[skin]}</span>
266|        <span className="picdraw-n">{DRAW_NOTE}</span>
267|      </div>
268|    </>
269|  );
