63|async function postImage(body: unknown): Promise<ImageResponse> {
64|  const res = await fetch("/api/images", {
65|    method: "POST",
66|    headers: { "Content-Type": "application/json" },
67|    body: JSON.stringify(body),
68|  });
69|  return (await res.json()) as ImageResponse;
70|}
71|
72|async function poll(body: unknown): Promise<{ url: string; caption: string }> {
73|  let left = POLL_MAX;
74|  for (;;) {
75|    let res: ImageResponse;
76|    try {
77|      res = await postImage(body);
78|    } catch {
79|      throw new Error(MSG_FAILED);
80|    }
81|    if (res.status === "ready") return { url: res.url, caption: res.caption };
82|    if (res.status === "error") throw new Error(res.message);
83|    left -= 1;
84|    if (left <= 0) throw new Error(MSG_RETRY);
85|    await new Promise((done) => setTimeout(done, POLL_MS));
86|  }
